-- Skill 1: Java (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111102',
    1,
    'Java Core & OOP Engineering Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"In Java, which memory area stores class-level variables (static) and bytecode metadata?","options":["Stack memory","Metaspace (formerly PermGen)","Heap Young Generation","Native Thread Stack"],"correctIndex":1,"explanation":"Since Java 8, class metadata and static variables are allocated in Metaspace (off-heap memory)."},{"id":2,"question":"What is the primary difference between Comparable and Comparator interfaces in Java?","options":["Comparable defines the natural ordering of objects (compareTo), while Comparator allows multiple custom sorting strategies (compare)","Comparable is only for primitive types, Comparator is for objects","Comparator is thread-safe, Comparable is not","Comparable is deprecated in Java 17"],"correctIndex":0,"explanation":"Comparable provides internal single natural sorting via compareTo(), whereas Comparator enables external custom sorting logic."},{"id":3,"question":"Why does Java prohibit multiple inheritance with classes but allows implementing multiple interfaces?","options":["To prevent heap fragmentation","To avoid the Diamond Problem (ambiguity in inheriting method implementations and state)","Because interfaces cannot define public methods","Because JVM bytecode cannot store multiple class parents"],"correctIndex":1,"explanation":"Multiple class inheritance leads to the Diamond Problem regarding method resolutions and state collisions."},{"id":4,"question":"What is the effect of the volatile keyword on a variable in multithreaded Java applications?","options":["It makes atomic compound operations like counter++ thread-safe","It guarantees immediate memory visibility across CPU cores by disabling CPU cache registers, but does not provide mutual exclusion","It serializes the variable into JSON","It automatically locks the entire object instance"],"correctIndex":1,"explanation":"volatile guarantees that reads and writes are visible to other threads immediately via cache coherence protocols."},{"id":5,"question":"Which Collection implementation in java.util provides O(1) average time complexity for key lookups without thread synchronization overhead?","options":["Hashtable","TreeMap","HashMap","ConcurrentHashMap"],"correctIndex":2,"explanation":"HashMap provides unsynchronized O(1) bucket hash-based lookups and insertions on average."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 3: SQL (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111103',
    3,
    'Relational SQL & Query Optimization Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"What is the key difference between WHERE and HAVING clauses in SQL?","options":["WHERE filters individual rows before aggregation; HAVING filters aggregated groups after GROUP BY","WHERE can only be used with subqueries","HAVING is executed before WHERE","There is no operational difference"],"correctIndex":0,"explanation":"WHERE applies conditions to individual table tuples before aggregation; HAVING applies conditions to aggregated group rows."},{"id":2,"question":"What does an EXPLAIN ANALYZE command output in PostgreSQL or modern SQL engines?","options":["It executes the query and prints the actual execution plan with node costs and real millisecond runtimes","It explains database disk encryption status","It deletes slow query logs","It simulates network latency"],"correctIndex":0,"explanation":"EXPLAIN ANALYZE executes the SQL statement and returns the query plan with actual timings, memory usage, and node statistics."},{"id":3,"question":"Which index type is the standard default for B-Tree indexing on primary and foreign keys in relational databases?","options":["Hash Index","B-Tree Index","GIN Index","BRIN Index"],"correctIndex":1,"explanation":"B-Tree is the universal default relational index supporting equality and range scans (<=, >=, BETWEEN)."},{"id":4,"question":"In SQL transaction isolation levels, what anomaly does SERIALIZABLE isolation prevent that REPEATABLE READ may allow?","options":["Dirty reads","Non-repeatable reads","Phantom reads and serialization anomalies","Loss of primary keys"],"correctIndex":2,"explanation":"SERIALIZABLE guarantees transactions behave as if executed sequentially, eliminating phantom reads and write skew."},{"id":5,"question":"What happens when a query performs a sequential scan (Seq Scan) instead of an Index Scan on a 5-million row table?","options":["The database crashes immediately","The engine reads every single page block from disk/buffer into memory, resulting in high I/O and latency","The index is automatically reconstructed","The result set returns in reverse order"],"correctIndex":1,"explanation":"Sequential scans iterate across all table disk blocks, causing heavy disk I/O when an appropriate index is missing."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 4: PostgreSQL (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111104',
    4,
    'PostgreSQL Advanced Database Engineering Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"What is the purpose of VACUUM in PostgreSQL Multi-Version Concurrency Control (MVCC)?","options":["To defragment CPU cache lines","To reclaim storage occupied by dead tuples from updated or deleted rows and prevent transaction ID wraparound","To reset database user passwords","To compress JPEG assets stored in bytea columns"],"correctIndex":1,"explanation":"PostgreSQL MVCC writes new row versions on update; VACUUM cleans up dead tuples and freezes transaction IDs to prevent wraparound."},{"id":2,"question":"Which PostgreSQL index type is specifically optimized for indexing JSONB arrays and full-text search (tsvector)?","options":["BRIN","GIN (Generalized Inverted Index)","B-Tree","Hash"],"correctIndex":1,"explanation":"GIN indexes are specialized for composite, multi-element types like JSONB keys/values, arrays, and tsvector document tokens."},{"id":3,"question":"What is the difference between JSON and JSONB data types in PostgreSQL?","options":["JSON stores raw textual formatting; JSONB stores parsed binary format, enabling indexing and faster operators (@>, ?&)","JSON is encrypted, JSONB is plaintext","JSONB only allows boolean values","JSON is deprecated in PostgreSQL 16"],"correctIndex":0,"explanation":"JSONB parses and stores structured binary data, supporting indexing and fast sub-document queries at the expense of slight write overhead."},{"id":4,"question":"How does PostgreSQL achieve connection pooling in production architectures handling thousands of client requests?","options":["By spawning a new JVM process per connection","By utilizing dedicated connection poolers like PgBouncer or Supabase Supavisor to multiplex client sockets over persistent backend workers","By increasing shared_buffers to 100 GB","By converting TCP connections to UDP"],"correctIndex":1,"explanation":"Because Postgres uses process-per-connection architecture, tools like PgBouncer prevent process contention under high concurrency."},{"id":5,"question":"What is the benefit of a Generated Column (STORED) in PostgreSQL 12+?","options":["It encrypts columns on disk","It computes column values from other columns automatically upon INSERT/UPDATE and persists them for instant indexed querying","It connects to external microservices","It prevents table drops"],"correctIndex":1,"explanation":"Stored generated columns calculate derived values deterministically from existing table attributes and store them for fast indexing."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 6: TypeScript (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111106',
    6,
    'TypeScript Strict Typing & Architecture Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"What is the key difference between any and unknown types in TypeScript?","options":["unknown enforces type-checking and narrowing before performing operations on the value, whereas any disables all compiler checks","any is strict, unknown is loose","unknown can only hold null or undefined","There is no runtime difference and both behave identically in the compiler"],"correctIndex":0,"explanation":"unknown is the type-safe counterpart of any; you cannot invoke methods or read properties on unknown without narrowing first."},{"id":2,"question":"What does the TypeScript keyof operator produce?","options":["A runtime array of object keys","A union type of all known public string, number, or symbol keys of a given type","A hash map of metadata","A boolean indicator of object equality"],"correctIndex":1,"explanation":"keyof T generates a union type comprising the property names of type T at compile time."},{"id":3,"question":"What is the purpose of TypeScript Generics (<T>)?","options":["To compile code into WebAssembly","To create reusable, type-safe components and functions that work across multiple types without losing type information","To generate randomized test mocks","To bypass strict null checks"],"correctIndex":1,"explanation":"Generics allow defining algorithms and data structures parameterized over types, ensuring strict compile-time verification."},{"id":4,"question":"How does TypeScript handle discriminated unions (tagged unions)?","options":["By looking up types in a database table","By checking a common literal property (e.g. type or status) to narrow down the union branch inside conditional blocks","By executing eval() at runtime","By converting unions to JavaScript classes"],"correctIndex":1,"explanation":"Discriminated unions rely on a common singleton discriminant property allowing TypeScript control-flow analysis to narrow types."},{"id":5,"question":"What is the result of using the as const assertion in TypeScript (e.g., const ROLES = [admin, provider] as const)?","options":["It seals the JavaScript object at runtime with Object.freeze()","It narrows all literal values to readonly literal types and creates a readonly tuple type rather than string[]","It imports the array from Node.js","It prevents variable reassignments but keeps array elements mutable"],"correctIndex":1,"explanation":"as const instructs the compiler to treat literal values as immutable literal types rather than widening them to primitive types."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 7: Python (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111107',
    7,
    'Python 3 & AI Engineering Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"How do Python generators (using the yield keyword) differ from standard functions returning lists?","options":["Generators execute on a separate GPU thread","Generators produce values lazily on-demand using the iterator protocol, preserving memory for large data pipelines","Generators are always slower than list comprehensions","Generators serialize return values into JSON"],"correctIndex":1,"explanation":"yield pauses function execution and emits items one at a time, conserving RAM when processing massive streams or datasets."},{"id":2,"question":"In Python, what is the role of the Global Interpreter Lock (GIL) in CPython?","options":["It encrypts bytecode before execution","It prevents multiple native threads from executing Python bytecode simultaneously within a single process","It limits memory allocation to 4 GB","It manages virtual environment dependencies"],"correctIndex":1,"explanation":"The CPython GIL synchronizes native thread access to Python objects, restricting multithreaded CPU-bound parallelism in a single process."},{"id":3,"question":"In FastAPI and modern Python services, what is Pydantic primarily used for?","options":["Managing database connections","Data validation, schema declaration, and runtime serialization using Python type hints","Serving static CSS and HTML assets","Training neural network weights"],"correctIndex":1,"explanation":"Pydantic performs fast, type-safe data parsing, validation, and JSON schema enforcement."},{"id":4,"question":"What is the time complexity of looking up a key in a standard Python dictionary (dict)?","options":["O(log n)","O(n)","O(1) average time complexity","O(n^2)"],"correctIndex":2,"explanation":"Python dictionaries are implemented as high-performance hash tables with average O(1) key lookups and insertions."},{"id":5,"question":"What does the Python @dataclass decorator automatically generate for a class?","options":["Database migration tables","Standard boilerplate methods like __init__(), __repr__(), and __eq__() based on typed class attributes","A Flask REST controller","A Docker container configuration"],"correctIndex":1,"explanation":"@dataclass inspects type annotations and auto-generates initialization, string representation, and equality comparison methods."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 8: Figma (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111108',
    8,
    'Figma UI Design & Component Systems Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"In Figma, what is the key benefit of Auto Layout over manual absolute positioning?","options":["It converts vector shapes to 3D meshes","Frames automatically adapt, resize, and re-flow child elements dynamically when content, language, or screen size changes","It increases resolution from 72 DPI to 300 DPI","It automatically writes backend REST APIs"],"correctIndex":1,"explanation":"Auto Layout mimics modern CSS Flexbox, ensuring responsive, resilient components that adapt to changing text lengths and viewports."},{"id":2,"question":"What are Figma Component Variants used for?","options":["To group multiple related states of a component (e.g. hover, active, disabled, dark mode) into a single configurable design asset","To export prototypes to Android APKs","To reduce the Figma file size on cloud storage","To bypass team permission settings"],"correctIndex":0,"explanation":"Component Variants bundle related variations of a UI element (sizes, states, icons) under structured property switches."},{"id":3,"question":"What is the function of Figma Variables (Design Tokens) in modern design systems?","options":["To store user passwords","To define semantic values (colors, typography, spacing, corner radius) that switch across light/dark themes and responsive modes","To animate SVG paths with JavaScript","To test internet connection speed"],"correctIndex":1,"explanation":"Variables manage reusable design tokens for color modes, spacing tokens, and themes across connected design files."},{"id":4,"question":"When handing off designs to frontend engineers, what critical CSS values does Figma Dev Mode provide directly?","options":["Database SQL queries","CSS flex/grid properties, spacing tokens, box shadows, hex/rgb colors, and asset exports","Java Spring Boot controllers","Git commit messages"],"correctIndex":1,"explanation":"Figma Dev Mode provides developers with pixel-accurate CSS, dimension tokens, typography rules, and asset download assets."},{"id":5,"question":"Why is establishing an 8px spacing grid considered a UI/UX industry standard?","options":["Because screens only display multiples of 8","It creates visual rhythm, predictable layout scaling, and maps cleanly to standard device screen densities and CSS rem units","It makes image file sizes smaller","Because Figma does not support odd pixel numbers"],"correctIndex":1,"explanation":"An 8pt/8px grid establishes aesthetic rhythm, reduces arbitrary design decisions, and aligns smoothly with digital displays."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 9: UI Design (TECH)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111109',
    9,
    'UI & UX Design Systems Assessment',
    'TECH',
    80,
    15,
    '[{"id":1,"question":"According to WCAG 2.1 AA accessibility guidelines, what is the minimum contrast ratio required for normal body text against its background?","options":["2:1","3:1","4.5:1","7:1"],"correctIndex":2,"explanation":"WCAG 2.1 AA requires a minimum contrast ratio of 4.5:1 for standard body text and 3:1 for large display text."},{"id":2,"question":"What is visual hierarchy in user interface design?","options":["The alphabetical sorting of navigation items","The arrangement and presentation of visual elements in an order that signifies importance and guides the users eye through contrast, scale, and color","The server architecture supporting the front page","The number of colors used in an illustration"],"correctIndex":1,"explanation":"Visual hierarchy structures information so users can intuitively comprehend content order, priority, and actions."},{"id":3,"question":"In mobile UI design for Ethiopian applications, why is designing for varying text length in Amharic (Fidäl) and English critical?","options":["Amharic text often expands or requires different vertical line-height (leading) to prevent glyph collisions compared to Latin scripts","Amharic text can only be displayed in monochrome","Latin scripts cannot be read on mobile devices","Amharic text renders upside down without special CSS"],"correctIndex":0,"explanation":"Ethiopic script characters have taller ascenders/descenders and varied character widths requiring flexible typography leading."},{"id":4,"question":"What is Fitts Law and how does it influence call-to-action (CTA) button design?","options":["It measures server response latency","The time required to rapidly move to a target area is a function of the ratio between distance and target width; therefore, primary buttons should be large and easily reachable","Users will abandon pages that take longer than 3 seconds to load","Dark mode reduces battery consumption on OLED screens"],"correctIndex":1,"explanation":"Fitts Law demonstrates that larger, closer targets are faster and easier for users to click or tap accurately."},{"id":5,"question":"What is the primary function of micro-interactions in a web or mobile application?","options":["To drain battery life","To provide immediate, delightful visual feedback confirming user actions (e.g., button loading spinner, success checkmark, toggle switch)","To inject background advertisements","To encrypt form submissions"],"correctIndex":1,"explanation":"Micro-interactions acknowledge user input, convey status transitions, and clarify interface feedback."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 10: Amharic–English Translation (LANGUAGE)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111110',
    10,
    'Amharic–English Professional Translation & Localization Assessment',
    'LANGUAGE',
    80,
    15,
    '[{"id":1,"question":"When translating professional contractual agreements from English to Amharic, how should legally binding terms like Terminate without cause be localized?","options":["ያለ ምክንያት ውል ማቋረጥ","ያለ ስራ መቀመጥ","ገንዘብ መከልከል","የስራ ማስታወቂያ"],"correctIndex":0,"explanation":"ያለ ምክንያት ውል ማቋረጥ is the standard, legally recognized Ethiopian contractual phrasing for termination without cause."},{"id":2,"question":"What grammatical distinction in Amharic verb morphology must be respected when translating direct instructions or polite address?","options":["Amharic verbs must always follow Subject-Verb-Object (SVO) order","Amharic incorporates formal/honorific verb agreement (e.g., እርሶ/ይመልከቱ) to convey professional courtesy and respect","Gender agreement does not exist in Amharic","Amharic has no past tense"],"correctIndex":1,"explanation":"Formal Amharic communication uses honorific forms to maintain respectful, professional register in enterprise contexts."},{"id":3,"question":"What is the difference between word-for-word translation (literal) and localized contextual adaptation (transcreation)?","options":["Literal translation translates words in isolation; contextual localization adapts idioms, cultural nuances, and tone to convey true intent naturally","Transcreation is done exclusively by AI without human review","Literal translation is used for poetry; transcreation is for technical manuals","There is no operational difference in modern translation"],"correctIndex":0,"explanation":"Contextual translation captures underlying semantic meaning and cultural nuance rather than mechanical literal equivalents."},{"id":4,"question":"In technical software localization for Ethiopian platforms, what is the best localized Amharic equivalent for Two-Factor Authentication (2FA)?","options":["ባለሁለት ደረጃ ማረጋገጫ","የይለፍ ቃል መቀየሪያ","የስልክ ቁጥር መደወያ","ድርብ ኢንተርኔት"],"correctIndex":0,"explanation":"ባለሁለት ደረጃ ማረጋገጫ accurately and universally denotes two-step/two-factor security authentication."},{"id":5,"question":"Which punctuation mark in the Ethiopic script (Fidäl) functions as a sentence terminator equivalent to the English period/full stop?","options":["ሁለት ነጥብ ( ፡ )","አራት ነጥብ ( ። )","ሰረዝ ( ፣ )","ድርብ ሰረዝ ( ፤ )"],"correctIndex":1,"explanation":"In Ethiopic orthography, አራት ነጥብ ( ። ) signifies the conclusion of a complete sentence."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 12: Pipefitting (TRADES)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111112',
    12,
    'Plumbing & Industrial Pipefitting Safety Assessment',
    'TRADES',
    80,
    15,
    '[{"id":1,"question":"What is the primary function of a P-Trap (waste water trap) beneath domestic sinks and drains?","options":["To increase water pressure in the faucet","To maintain a water seal that prevents toxic sewer gases and foul odors from entering the building","To filter microplastics from drinking water","To heat incoming cold water"],"correctIndex":1,"explanation":"P-traps hold a standing water barrier preventing sewer gases (methane, hydrogen sulfide) from rising through fixtures."},{"id":2,"question":"When joining threaded galvanized or brass water pipes, what material is standardly wrapped clockwise around male threads to ensure leak-proof seals?","options":["Electrical tape","PTFE / Teflon Thread Seal Tape or approved pipe joint compound","Super glue","Cotton string"],"correctIndex":1,"explanation":"PTFE (Teflon) tape lubricates thread assembly and deforms into thread crests to create a watertight seal."},{"id":3,"question":"What does hydrostatic pressure testing verify on newly installed water distribution or heating pipelines?","options":["Pipe color consistency","Pipeline structural integrity, joint seal quality, and leak absence under 1.5x working operating pressure","Water temperature","Electrical conductivity of the pipe"],"correctIndex":1,"explanation":"Hydrostatic pressure tests pressurize pipelines with water above normal working load to confirm zero leakage before wall closure."},{"id":4,"question":"In PPR (Polypropylene Random Copolymer) piping installations standard in Ethiopian buildings, what method joins pipes and fittings?","options":["Solvent cement glue","Thermal fusion / heat welding using an electric welding iron at ~260°C","Nails and bolts","Duct tape"],"correctIndex":1,"explanation":"PPR piping uses thermal socket fusion to melt pipe and fitting surfaces into a seamless homogeneous molecular bond."},{"id":5,"question":"Why must a Pressure Relief Valve (PRV / T&P Valve) be installed on every domestic water heater (geyser)?","options":["To save electricity","To prevent catastrophic tank explosion by venting water if temperature or pressure exceeds safe thresholds","To turn off the water heater at night","To increase hot water volume"],"correctIndex":1,"explanation":"Temperature and Pressure (T&P) relief valves are critical safety devices preventing water heater rupture or boiling explosions."}]'
) ON CONFLICT (id) DO NOTHING;

-- Skill 13: Communication (SOFT)
INSERT INTO skill_assessment (id, skill_id, title, category, passing_score, time_limit_minutes, questions_json)
VALUES (
    'e1111111-1111-1111-1111-111111111113',
    13,
    'Professional Workplace & Client Communication Assessment',
    'SOFT',
    80,
    15,
    '[{"id":1,"question":"What is active listening in professional client and stakeholder interactions?","options":["Waiting impatiently for the other person to stop talking so you can respond","Fully focusing, comprehending, reflecting back key points, and asking clarifying questions before formulating a solution","Multitasking on your phone during a meeting","Recording the conversation without permission"],"correctIndex":1,"explanation":"Active listening involves focused attention, verbal affirmation, and clarifying ambiguity to ensure complete alignment."},{"id":2,"question":"When encountering an unexpected technical blocker that will delay an agreed contract milestone, what is the best professional approach?","options":["Wait until the deadline has passed and apologize later","Proactively notify the client immediately, explain the root challenge clearly, and provide revised options or mitigation timelines","Blame third-party software without giving solutions","Mark the milestone as delivered anyway"],"correctIndex":1,"explanation":"Proactive, transparent communication with concrete options builds trust and preserves professional credibility."},{"id":3,"question":"In written workplace messages, what is the primary benefit of the BLUF (Bottom Line Up Front) communication technique?","options":["It makes emails longer","It states the core conclusion, request, or recommendation in the first sentence so busy readers immediately grasp the purpose","It hides critical details in postscripts","It prevents recipients from replying"],"correctIndex":1,"explanation":"BLUF respects executive/client time by stating key findings and actionable asks immediately before providing context."},{"id":4,"question":"How should a professional service provider de-escalate tension when a client expresses frustration regarding a deliverable?","options":["Argue aggressively and point out client mistakes","Acknowledge their concern with empathy, remain calm, clarify specific gaps, and focus collaboratively on an actionable resolution","Ignore the messages until the client calms down","Cancel the contract immediately"],"correctIndex":1,"explanation":"De-escalation combines empathetic acknowledgment, objective clarification of issues, and structured problem-solving."},{"id":5,"question":"Why is documenting agreements, deliverables, and revision scopes in writing via the platform contract critical?","options":["To avoid human interaction","To ensure mutual clarity, eliminate misunderstandings, and protect both parties with an objective audit trail","To increase platform fees","Because verbal promises are forbidden by law"],"correctIndex":1,"explanation":"Written contract scopes align expectations on milestones, deliverables, and boundaries, preventing disputes."}]'
) ON CONFLICT (id) DO NOTHING;
